import fs from 'node:fs';

const mainPath='src/main.jsx';
let s=fs.readFileSync(mainPath,'utf8');

// Fund ledger: color the actual movement row and amount. This runs LAST,
// after the fund component has been generated by the earlier build transforms.
s=s.replace(
  "<tbody>{transactions.map(x=><tr key={x.id} className={x.transaction_type==='expense'?'expense-row':''}>",
  "<tbody>{transactions.map(x=><tr key={x.id} className={x.transaction_type==='expense'?'expense-row':'income-row'}>"
);
s=s.replace(
  "<td className={x.transaction_type==='expense'?'expense-amount':'income-amount'}><b>{x.transaction_type==='expense'?'−':'+'}{money(x.amount)}</b></td>",
  "<td className={x.transaction_type==='expense'?'expense-amount':'income-amount'}><strong>{x.transaction_type==='expense'?'−':'+'}{money(x.amount)}</strong></td>"
);

// Monthly payout ledger: paid rows are green, unpaid rows are red.
s=s.replace(
  "<tbody>{active.map((c,i)=>{const paid=isPaid(c.id);return <tr id={'payment-row-'+c.id} key={c.id}>",
  "<tbody>{active.map((c,i)=>{const paid=isPaid(c.id);return <tr id={'payment-row-'+c.id} key={c.id} className={paid?'payment-row paid':'payment-row unpaid'}>"
);
s=s.replace(
  "<td>{money(caseAmount(c,amounts))}</td><td><button disabled={busy} className={paid?'payment-toggle paid':'payment-toggle'}",
  "<td className={paid?'payment-amount paid':'payment-amount unpaid'}><strong>{money(caseAmount(c,amounts))}</strong></td><td><button disabled={busy} className={paid?'payment-toggle paid':'payment-toggle unpaid'}"
);

// Make the monthly totals themselves visually communicate money movement.
s=s.replace(
  '<article className="stat"><span>تم الصرف</span><strong>{money(paidTotal)}</strong></article><article className="stat"><span>لم يتم الصرف</span><strong>{money(unpaidTotal)}</strong></article>',
  '<article className="stat payment-total-card paid"><span>تم الصرف</span><strong>{money(paidTotal)}</strong><small>خرج من رصيد المسجد</small></article><article className="stat payment-total-card unpaid"><span>لم يتم الصرف</span><strong>{money(unpaidTotal)}</strong><small>ما زال في رصيد المسجد</small></article>'
);

// Clarify that external distribution approval and actual receipt are separate.
s=s.replace(
  '<p>حدد الشهر ثم علّم الحالات التي تم صرف المساعدة لها. عدم القبض لا يُرحّل للشهر التالي.</p>',
  '<p>اعتماد التوزيع الخارجي لا يعني القبض. حدّد يدويًا من قبض بالضغط على «تم القبض». عدم القبض لا يُرحّل للشهر التالي.</p>'
);

fs.writeFileSync(mainPath,s);

const fundCss='src/styles.css';
let f=fs.readFileSync(fundCss,'utf8');
const fundUi=`
/* Final fund ledger table UI */
.fund-history .payment-table-wrap{border:1px solid #e0e5eb;border-radius:16px;overflow:auto;background:#fff}
.fund-history .payment-table{min-width:820px;width:100%;border-collapse:separate;border-spacing:0}
.fund-history .payment-table th{height:46px;padding:10px 14px;background:#f6f8fa;color:#667085;font-size:12px;border-bottom:1px solid #dde2e8;white-space:nowrap}
.fund-history .payment-table td{height:58px;padding:11px 14px;border-bottom:1px solid #edf0f3;vertical-align:middle}
.fund-history .payment-table tbody tr.income-row{background:#f3fbf6}
.fund-history .payment-table tbody tr.expense-row{background:#fff5f4}
.fund-history .payment-table tbody tr.income-row:hover{background:#e9f7ee}
.fund-history .payment-table tbody tr.expense-row:hover{background:#ffebe9}
.fund-history .payment-table .income-amount{color:#16713b!important}
.fund-history .payment-table .expense-amount{color:#b52f27!important}
.fund-history .payment-table .income-amount strong,.fund-history .payment-table .expense-amount strong{font-size:16px;font-weight:900;white-space:nowrap}
.fund-history .payment-table .transaction-badge.income{background:#e8f6ed;color:#16713b;border:1px solid #bfe2cb}
.fund-history .payment-table .transaction-badge.expense{background:#fdebea;color:#b52f27;border:1px solid #efc2be}

/* Monthly payout table */
.payment-page .payment-table-wrap{border:1px solid #e0e5eb;border-radius:16px;overflow:auto;background:#fff;box-shadow:0 5px 18px rgba(16,24,40,.04)}
.payment-page .payment-table{min-width:760px;width:100%;border-collapse:separate;border-spacing:0}
.payment-page .payment-table th{height:48px;padding:11px 14px;background:#f6f8fa;color:#667085;font-size:12px;border-bottom:1px solid #dde2e8;white-space:nowrap}
.payment-page .payment-table td{height:60px;padding:11px 14px;border-bottom:1px solid #edf0f3;vertical-align:middle}
.payment-page .payment-table tbody tr.paid{background:#f3fbf6}
.payment-page .payment-table tbody tr.unpaid{background:#fff5f4}
.payment-page .payment-table tbody tr.paid:hover{background:#e9f7ee}
.payment-page .payment-table tbody tr.unpaid:hover{background:#ffebe9}
.payment-page .payment-table .payment-amount.paid{color:#16713b!important}
.payment-page .payment-table .payment-amount.unpaid{color:#b52f27!important}
.payment-page .payment-table .payment-amount strong{font-size:15px;font-weight:900;white-space:nowrap}
.payment-page .payment-toggle{min-width:132px;font-size:12px;font-weight:800}
.payment-page .payment-toggle.paid{border-color:#b9ddc5;background:#eaf7ee;color:#176f39}
.payment-page .payment-toggle.unpaid{border-color:#efc2be;background:#fdeceb;color:#b52f27}
.payment-page .payment-total-card.paid{background:#f0faf4;border:1px solid #bfe2cb}
.payment-page .payment-total-card.paid span,.payment-page .payment-total-card.paid strong{color:#16713b}
.payment-page .payment-total-card.unpaid{background:#fff3f2;border:1px solid #efc2be}
.payment-page .payment-total-card.unpaid span,.payment-page .payment-total-card.unpaid strong{color:#b52f27}
.payment-page .payment-total-card small{display:block;margin-top:5px;font-size:11px;font-weight:700;opacity:.78}
@media(max-width:700px){.fund-history .payment-table,.payment-page .payment-table{min-width:760px}.fund-history .payment-table th,.fund-history .payment-table td,.payment-page .payment-table th,.payment-page .payment-table td{padding:10px 11px}}
`;
if(!f.includes('Final fund ledger table UI')) f+=fundUi;
fs.writeFileSync(fundCss,f);

console.log('Fund ledger and monthly payout UI finalized safely.');
